I'll create an HTMLPreview component and update the Code component to detect and display HTML blocks in an iframe.

## Summary of Changes

| File | Changes |
|------|---------|
| `src/components/HTMLPreview.vue` | **NEW** - Component to render HTML in sandboxed iframe |
| `src/components/Code.vue` | Updated to detect HTML language and show preview button |

---

## New Component

```vue src/components/HTMLPreview.vue
<script setup>
import { ref } from 'vue'
</script>

<template>
  <div class="h-full flex flex-col">
    <div class="flex gap-2 p-2 border-b border-slate-500">
      <button 
        class="btn btn-xs btn-outline"
        @click="refreshPreview"
        title="Refresh preview"
      >
        <i class="fa-solid fa-arrows-rotate"></i>
        <span class="hidden sm:inline">Refresh</span>
      </button>
      <button 
        class="btn btn-xs btn-outline"
        @click="toggleFullscreen"
        title="Toggle fullscreen"
      >
        <i class="fa-solid fa-expand"></i>
      </button>
    </div>

    <div class="flex-1 overflow-auto" ref="previewContainer">
      <iframe
        ref="previewFrame"
        class="w-full h-full border-0"
        :key="refreshCounter"
        sandbox="allow-scripts allow-same-origin allow-forms"
        title="HTML Preview"
      ></iframe>
    </div>
  </div>
</template>

<script>
export default {
  props: ['html'],
  data() {
    return {
      refreshCounter: 0
    }
  },
  watch: {
    html(newHtml) {
      this.$nextTick(() => {
        this.renderHTML(newHtml)
      })
    }
  },
  mounted() {
    this.renderHTML(this.html)
  },
  methods: {
    renderHTML(htmlContent) {
      const iframe = this.$refs.previewFrame
      if (!iframe) return

      try {
        const doc = iframe.contentDocument || iframe.contentWindow.document
        doc.open()
        doc.write(`
          <!DOCTYPE html>
          <html>
          <head>
            <meta charset="UTF-8">
            <meta name="viewport" content="width=device-width, initial-scale=1.0">
            <style>
              body {
                margin: 0;
                padding: 1rem;
                font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
                background-color: #0f172a;
                color: #e2e8f0;
              }
            </style>
          </head>
          <body>
            ${htmlContent}
          </body>
          </html>
        `)
        doc.close()
      } catch (error) {
        console.error('Error rendering HTML preview:', error)
      }
    },

    refreshPreview() {
      this.refreshCounter++
      this.$nextTick(() => {
        this.renderHTML(this.html)
      })
    },

    toggleFullscreen() {
      const iframe = this.$refs.previewFrame
      if (!iframe) return

      if (iframe.requestFullscreen) {
        iframe.requestFullscreen()
      } else if (iframe.webkitRequestFullscreen) {
        iframe.webkitRequestFullscreen()
      }
    }
  }
}
</script>
```

